import re, os
outdir = r"./"
def tables(html):
    res=[]
    for m in re.finditer(r"<table[^>]*>.*?</table>", html, flags=re.S|re.I):
        t=m.group(0)
        rows=re.findall(r"<tr[^>]*>.*?</tr>", t, flags=re.S|re.I)
        out=[]
        for r in row./            cells=re.findall(r"<t[dh][^>]*>(.*?)</t[dh]>", r, flags=re.S|re.I)
            cells=[re.sub(r"\s+"," ",re.sub(r"<[^>]+>"," ",c)).strip() for c in cells]
            cells=[c for c in cells if c]
            if cells: out.append(" | ".join(cells))
        res.append(out)
    return res
for k in ["ganyu","xiao"]:
    html=open(os.path.join(outdir,f"_cache_{k}.html"),encoding="utf-8").read()
    ts=tables(html)
    print(f"##### {k}: {len(ts)} tables")
    for i,t in enumerate(ts):
        blob=" ".join(t)
        prev=blob[:90].replace("\n"," ")
        tag=[]
        for kw in ["命","天赋","%","等级","生命值","冷却","元素能量","蓄力"]:
            if kw in blob: tag.append(kw)
        print(f"[{i}] rows={len(t)} chars={len(blob)} tags={','.join(tag)} :: {prev}")
"}

